local function isMobile()
    return UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled
end

local function getScale()
    local viewport = Workspace.CurrentCamera.ViewportSize
    return math.clamp(math.min(viewport.X, viewport.Y) / 800, 0.7, 1.2)
end

local function hasFileSystem()
    local ok1 = pcall(function() return type(writefile) == "function" end)
    local ok2 = pcall(function() return type(readfile) == "function" end)
    local ok3 = pcall(function() return type(isfile) == "function" end)
    return ok1 and ok2 and ok3
end

local fileSystemSupported = hasFileSystem()

local function saveKey(key)
    if not fileSystemSupported then return false end
    local ok = pcall(function() writefile(Config.key_file, key) end)
    return ok
end

local function loadKey()
    if not fileSystemSupported then return nil end
    local ok, content = pcall(function()
        if isfile(Config.key_file) then
            return readfile(Config.key_file)
        end
        return nil
    end)
    if ok and content and content ~= "" then return content end
    return nil
end

local function clearKey()
    if not fileSystemSupported then return false end
    local ok = pcall(function() delfile(Config.key_file) end)
    return ok
end

